Para desarrollar un programa en C++ que lea un archivo de texto línea por línea y cuente el número de apariciones de una palabra específica, puedes seguir los siguientes pasos y utilizar el siguiente código como guía. Este programa utiliza las bibliotecas estándar de C++, incluyendo `<iostream>`, `<fstream>`, y `<string>`.

```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int countWordInFile(const string& word, const string& filename) {
    ifstream file(filename);
    if (!file.is_open()) {
        cerr << "Error al abrir el archivo: " << filename << endl;
        return -1;
    }

    string currentWord;
    int count = 0;
    while (file >> currentWord) {
        if (currentWord == word) {
            count++;
        }
    }

    file.close();
    return count;
}

int main() {
    string filename;
    string word;

    cout << "Ingrese el nombre del archivo: ";
    cin >> filename;
    cout << "Ingrese la palabra a buscar: ";
    cin >> word;

    int count = countWordInFile(word, filename);

    if (count != -1) {
        cout << "La palabra '" << word << "' aparece " << count << " veces en el archivo." << endl;
    }

    return 0;
}
```

### Explicación del código:
