int fibonacciMemoization(int i, int n, int* memoization) {
    if (memoization[i] != -1) {
        return memoization[i];
    }
    if (i == 0) {
        memoization[i] = fibonacci[0];
        return fibonacci[0];
    }
    if (i == 1) {
        memoization[i] = fibonacci[1];
        return fibonacci[1];
    }
    memoization[i] = fibonacciMemoization(i - 1, n, memoization) + fibonacciMemoization(i - 2, n, memoization);
    return memoization[i];
}

